const equal3 = (a, b) => Array.isArray(a) && a.length === 3 && a.every((v, i) => Number.isFinite(v) && v === b[i]);
function sourceProfile(row) {
  if (!row || row.proxy?.appendGenericPrinterCues === false) return null;
  const profile = profiles.get(row.id);
  if (!profile) return null;
  const d = row.dimensionsMm;
  if (!d || !equal3([d.width, d.height, d.depth], profile.d) ||
      !equal3(row.fullScene?.translationM, profile.t) ||
      (row.fullScene?.providerDefaultPose?.recipeSha256 ?? null) !== profile.r ||
      (row.fullScene?.providerDefaultPose?.actualStateSha256 ?? null) !== profile.s ||
      (Array.isArray(row.sourceEvidence?.metadata) && !profile.m.every(hash => row.sourceEvidence.metadata.some(m => m.sha256 === hash))) ||
      (profile.i && !row.sourceEvidence?.sources?.some(s => s.repository === profile.i[0] && s.revision === profile.i[1] && s.sha256 === profile.i[2]))) return null;
  return profile;
}

/** Fresh source-backed preview descriptors; unsupported/stale rows return []. */
export function printerSilhouetteParts(row) {
  const profile = sourceProfile(row);
  if (!profile) return [];
  const existing = new Set((row.proxy?.parts || []).filter(p => !p.wireframe).map(p => p.sourcePartKey));
  return profile.p.filter(p => !existing.has(p[1])).slice(0, 32).map(([proxyRole, sourcePartKey, sizeM, centerM, color, opacity = null, shape = null, axis = null]) => ({
    sizeM: [...sizeM], centerM: [...centerM], color, proxyRole, sourcePartKey,
    ...(opacity === null ? {} : {opacity}), ...(shape === null ? {} : {shape}),
    ...(axis === null ? {} : {axis}), previewCue: true
  }));
}

/** Fresh source-key roles, including retained catalog boxes; geometry stays new-only. */
export function printerSilhouetteSourceRoles(row) {
  const profile = sourceProfile(row);
  if (!profile) return {};
  return Object.fromEntries([...profile.p.map(p => [p[1], p[0]]), ...Object.entries(profile.a || {})]);
}
